48	    return [{ d: null, color: DONUT_PALETTE[0] }];
49	  }
50	  let angle = -Math.PI / 2;
51	  return entries.map(([, val], i) => {
52	    const sweep = (val / total) * 2 * Math.PI;
53	    const x1 = cx + R * Math.cos(angle);
54	    const y1 = cy + R * Math.sin(angle);
55	    const x2 = cx + R * Math.cos(angle + sweep);
56	    const y2 = cy + R * Math.sin(angle + sweep);
57	    const large = sweep > Math.PI ? 1 : 0;
58	    angle += sweep;
59	    return {
60	      d: `M${cx},${cy} L${x1},${y1} A${R},${R} 0 ${large},1 ${x2},${y2} Z`,
61	      color: DONUT_PALETTE[i % DONUT_PALETTE.length],
62	    };
63	  });
64	}
